const b = $input.first().json.body || $input.first().json;
const esc = (s) => (s == null || s === '') ? 'NULL' : `'${String(s).replace(/'/g, "''")}'`;
const num = (n) => (n == null || n === '' || isNaN(Number(n))) ? 'NULL' : Number(n);
const lit = (s) => String(s == null ? '' : s).replace(/'/g, "''");
const detail = JSON.stringify(b.detail || {}).replace(/'/g, "''");

const insertLead = `INSERT INTO leads (lead_type, model, variant, color, pay_type, down_pct, installment, period, price, cust_name, cust_phone, line_user_id, detail)
VALUES (${esc(b.lead_type)}, ${esc(b.model)}, ${esc(b.variant)}, ${esc(b.color)}, ${esc(b.pay_type)}, ${num(b.down_pct)}, ${num(b.installment)}, ${num(b.period)}, ${num(b.price)}, ${esc(b.cust_name)}, ${esc(b.cust_phone)}, ${esc(b.line_user_id)}, '${detail}'::jsonb);`;

let interest = b.model || '';
if (b.lead_type === 'tradein' && b.detail && b.detail.new_model) interest = b.detail.new_model;
const dispName = b.line_name || b.cust_name || '';
const uid = lit(b.line_user_id);
let upsertCust = '';
if (uid) {
  upsertCust = `WITH old AS (SELECT status AS prev_status FROM customers WHERE line_user_id='${uid}')
INSERT INTO customers (line_user_id, display_name, phone, interest_model, lead_count, last_seen, updated_at)
VALUES ('${uid}', ${esc(dispName)}, ${esc(b.cust_phone)}, ${esc(interest)}, 1, NOW(), NOW())
ON CONFLICT (line_user_id) DO UPDATE SET
  display_name = COALESCE(customers.display_name, NULLIF(EXCLUDED.display_name, '')),
  phone = COALESCE(NULLIF(EXCLUDED.phone, ''), customers.phone),
  interest_model = COALESCE(NULLIF(EXCLUDED.interest_model, ''), customers.interest_model),
  lead_count = customers.lead_count + 1,
  status = CASE WHEN customers.status IN ('approved','rejected') THEN 'new' ELSE customers.status END,
  assignee = CASE WHEN customers.status IN ('approved','rejected') THEN NULL ELSE customers.assignee END,
  last_seen = NOW(),
  updated_at = NOW()
RETURNING id, lead_count, (SELECT prev_status FROM old) AS prev_status;`;
}

return [{ json: { sql: insertLead + '\n' + upsertCust, lead: b } }];

// ====== CONFIG ======
const SALES_TOKEN = 'SALES_TOKEN_HERE';
const SALES_GROUP_ID = 'SALES_GROUP_ID_HERE';

const L = $('Build SQL').first().json.lead || {};
let row = {};
try { row = $('Insert').first().json || {}; } catch (e) {}
const custId = row.id || null;
const prevStatus = row.prev_status || null; // null = ลูกค้าใหม่
const code = custId ? ('PP-' + String(custId).padStart(4, '0')) : 'PP-????';
const uid = L.line_user_id || '';
const custName = (L.line_name || L.cust_name || '').trim() || 'ลูกค้า LINE';

const TYPE = {
  installment: { label: 'ผ่อน', color: '#1eaa5c', emoji: '🟢' },
  cash:        { label: 'เงินสด', color: '#1eaa5c', emoji: '🟢' },
  tradein:     { label: 'เทิร์นรถเก่า', color: '#f57c00', emoji: '🟠' },
  testride:    { label: 'ทดลองขับ', color: '#2563eb', emoji: '🔵' }
};
const t = TYPE[L.lead_type] || { label: L.lead_type || 'lead', color: '#666666', emoji: '🔔' };
const baht = (n) => '฿' + Number(n || 0).toLocaleString('en-US');

const lines = [];
if (L.lead_type === 'installment') {
  lines.push('💳 ค่างวด ' + baht(L.installment) + ' × ' + (L.period || '-') + ' ด.');
  if (L.down_pct != null && L.down_pct !== '') lines.push('เงินดาวน์ ' + L.down_pct + '%');
} else if (L.lead_type === 'cash') {
  lines.push('💵 เงินสด ' + baht(L.price));
} else if (L.lead_type === 'tradein') {
  lines.push('🔄 รถเทิร์น: ' + (L.model || '-'));
  const nm = (L.detail && L.detail.new_model) || '';
  if (nm) lines.push('อยากได้: ' + nm);
} else if (L.lead_type === 'testride') {
  lines.push('🏍️ ลองรุ่น: ' + (L.model || '-'));
  const dt = (L.detail && L.detail.datetime) || (L.detail && L.detail.date) || '';
  if (dt) lines.push('📅 ' + dt);
}

const variantColor = [L.variant, L.color].filter(Boolean).join(' · ');
const phone = L.cust_phone ? ('📞 ' + L.cust_phone) : '📞 (รอลูกค้าฝากเบอร์)';

const body = [
  { type: 'box', layout: 'vertical', backgroundColor: t.color, cornerRadius: '6px', paddingAll: '8px',
    contents: [{ type: 'text', text: t.emoji + ' ลูกค้าใหม่ · ' + t.label, color: '#ffffff', weight: 'bold', size: 'sm' }] },
  { type: 'text', text: '👤 ' + custName, weight: 'bold', size: 'xl', margin: 'md', wrap: true },
  { type: 'text', text: (L.model || '-'), size: 'md', wrap: true, margin: 'sm' }
];
if (variantColor) body.push({ type: 'text', text: variantColor, size: 'sm', color: '#888888' });
lines.forEach(d => body.push({ type: 'text', text: d, size: 'sm', wrap: true, margin: 'sm' }));
body.push({ type: 'text', text: phone, size: 'sm', margin: 'sm' });
body.push({ type: 'text', text: '🔴 รอติดต่อ', size: 'sm', weight: 'bold', color: '#cc0000', margin: 'sm' });

const flex = {
  type: 'flex', altText: 'ลูกค้าใหม่ ' + custName + ' (' + t.label + ')',
  contents: {
    type: 'bubble',
    body: { type: 'box', layout: 'vertical', spacing: 'sm', contents: body },
    footer: { type: 'box', layout: 'vertical', spacing: 'sm', contents: [
      { type: 'button', style: 'primary', color: t.color, height: 'sm',
        action: { type: 'postback', label: '📞 รับเคส', data: 'action=claim&cid=' + uid, displayText: 'รับเคส ' + custName } },
      { type: 'box', layout: 'horizontal', spacing: 'sm', contents: [
        { type: 'button', style: 'secondary', height: 'sm',
          action: { type: 'postback', label: '✅ อนุมัติ', data: 'action=approve&cid=' + uid, displayText: 'อนุมัติ ' + custName } },
        { type: 'button', style: 'secondary', height: 'sm',
          action: { type: 'postback', label: '❌ ไม่ผ่าน', data: 'action=reject&cid=' + uid, displayText: 'ไม่ผ่าน ' + custName } }
      ]},
      { type: 'text', text: code, size: 'xs', color: '#cccccc', align: 'end', margin: 'sm' }
    ]}
  }
};

const configured = SALES_GROUP_ID && SALES_GROUP_ID !== 'SALES_GROUP_ID_HERE' && SALES_TOKEN !== 'SALES_TOKEN_HERE';
const fresh = (!prevStatus) || prevStatus === 'approved' || prevStatus === 'rejected'; // ใหม่ หรือ กลับมาใหม่
const doPush = !!(custId && configured && fresh);

return [{ json: { to: SALES_GROUP_ID, messages: [flex], token: SALES_TOKEN, doPush: doPush } }];
